"use strict";(self.webpackChunkrrbtc_wiki_docusaurus=self.webpackChunkrrbtc_wiki_docusaurus||[]).push([[33384],{67276(e){e.exports=JSON.parse('{"tag":{"label":"signing-device","permalink":"/tags/signing-device","allTagsPath":"/tags","count":5,"items":[{"id":"entities/jade-diy","title":"Jade DIY","description":"Jade DIY is Blockstream\'s open-source firmware for the Blockstream Jade hardware wallet, made available for installation on compatible off-the-shelf hardware. The project lets users build and verify their own Jade-compatible signing device from generic components.","permalink":"/entities/jade-diy"},{"id":"entities/krux","title":"Krux","description":"Krux is open-source firmware that enables anyone to build a Bitcoin signing device from off-the-shelf parts. It runs on cheap, general-purpose microcontrollers (e.g. M5StickV, Maix Amigo, Maix Dock) and turns them into air-gapped signing devices.","permalink":"/entities/krux"},{"id":"entities/seedsigner","title":"SeedSigner","description":"Open-source, DIY Bitcoin signing device built from commodity hardware. Designed for air-gapped seed generation, transaction signing, and multisig coordination without trusting proprietary hardware.","permalink":"/entities/seedsigner"},{"id":"entities/specter-diy","title":"Specter DIY","description":"Specter DIY is an open-source, do-it-yourself hardware wallet project from the Specter suite. It turns commodity hardware into an air-gapped signing device that pairs with Specter Desktop for multisig and single-sig custody.","permalink":"/entities/specter-diy"},{"id":"entities/tapsigner","title":"Tapsigner","description":"NFC-enabled card from Coinkite storing a Bitcoin private key. Sign transactions by tapping the card to your phone.","permalink":"/entities/tapsigner"}],"unlisted":false}}')}}]);